/** The GRKU version, which vite.config.ts reads from the workspace Cargo.toml. */
declare const __GRKU_VERSION__: string;
/** The build signature, `GRKU·BOTNICK·<version>·<commit>` (scripts/build-signature.mjs). */
declare const __GRKU_SIG__: string;
/** The day the manual last changed (YYYY-MM-DD), or null (vite.config.ts). */
declare const __DOCS_UPDATED__: string | null;
